/**
 * Boots the mock backend: registers every handler module, then starts the
 * simulators. Import order is registration order.
 *
 * Owner: seed agent. Feature groups do NOT edit this file; they fill their own
 * src/demo/handlers/<group>.ts (wired in by ./handlers/index.ts) and
 * src/demo/simulators/<group>.ts (started below).
 */
import './handlers'

import { startCampaignsSimulator } from './simulators/campaigns'
import { startInsightsSimulator } from './simulators/insights'
import { startStaffSimulator } from './simulators/staff'
import { startSync } from './sync'

export { api, bus, clock, generateToken, resetDemoData, session, store } from './core'

let stopAll: (() => void) | null = null

/** Start the simulators and the optional two-tab mirror once. Returns a stop function (HMR, tests). */
export function bootDemo(): () => void {
  if (stopAll) return stopAll
  const stops = [startInsightsSimulator(), startCampaignsSimulator(), startStaffSimulator(), startSync()]
  stopAll = () => {
    for (const stop of stops) stop()
    stopAll = null
  }
  return stopAll
}
